            throw std::out_of_range("Queue is empty");
        }
        T frontData = frontPtr->data;
        Node* temp = frontPtr;
        frontPtr = frontPtr->next;
        delete temp;
        if (frontPtr == nullptr) {
            rearPtr = nullptr;
        }
        return frontData;
    }

    T front() {
        if (isEmpty()) {
            throw std::out_of_range("Queue is empty");
        }
        return frontPtr->data;
    }

    bool isEmpty() {
        return frontPtr == nullptr;
    }

    ~Queue() {
        while (frontPtr != nullptr) {
            Node* temp = frontPtr;
            frontPtr = frontPtr->next;
            delete temp;
        }
        rearPtr = nullptr;
    }
};

