void DynamicArray<T>::reserve(size_t additional) {
    if (additional > capacity) {
        size_t new_capacity = capacity * 2; // Using a growth factor of 2 for simplicity
        if (new_capacity < size + additional) {
            new_capacity = size + additional; // Ensure capacity is sufficient for additional elements
        }
        T* new_data = new T[new_capacity]; // Allocate memory for the new array
        for (size_t i = 0; i < size; ++i) {
            new_data[i] = data[i]; // Copy existing elements to the new array
