                __m512d b_avx512 = _mm512_load_pd(&B[k * p + j]);  // Load 8 elements from B using AVX512
                sum_avx512 = _mm512_fmadd_pd(a_avx512, b_avx512, sum_avx512);  // Perform fused multiply-add using AVX512
            }

