double NormalizedModel::calculateStandardDeviation() const {
    double mean = calculateMean();
    double sum = 0.0;
    for (double value : originalData) {
        sum += (value - mean) * (value - mean);
    }
    double variance = sum / originalData.size();
    return std::sqrt(variance);
}

