class CircularBuffer : public Reader, public Writer {
  static const uint32_t BUFFER_SIZE = 1024;
  uint32_t last_sender_id_;
  uint32_t n_callbacks_logged_;
  uint32_t dummy_wr_;
  uint32_t dummy_rd_;
  uint8_t dummy_buff_[BUFFER_SIZE];

