class FDSet {
private:
    fd_set set;

public:
    FDSet() {
        FD_ZERO(&set);
    }

    void addFileDescriptor(int fd) {
        FD_SET(fd, &set);
    }

    void removeFileDescriptor(int fd) {
        FD_CLR(fd, &set);
    }

    fd_set* getSet() {
        return &set;
    }
