struct Point {
    double x, y;
};

struct Line {
    Point start, end;
};

bool onSegment(const Point& p, const Point& q, const Point& r) {
    if (q.x <= std::max(p.x, r.x) && q.x >= std::min(p.x, r.x) &&
        q.y <= std::max(p.y, r.y) && q.y >= std::min(p.y, r.y)) {
        return true;
    }
    return false;
}

int orientation(const Point& p, const Point& q, const Point& r) {
    double val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
    if (std::abs(val) < 1e-9) {
        return 0;  // Collinear
    }
    return (val > 0) ? 1 : 2;  // Clockwise or counterclockwise
}

bool doIntersect(const Line& l1, const Line& l2) {
    int o1 = orientation(l1.start, l1.end, l2.start);
    int o2 = orientation(l1.start, l1.end, l2.end);
    int o3 = orientation(l2.start, l2.end, l1.start);
    int o4 = orientation(l2.start, l2.end, l1.end);

    if (o1 != o2 && o3 != o4) {
        return true;
    }

    if (o1 == 0 && onSegment(l1.start, l2.start, l1.end)) {
        return true;
    }

    if (o2 == 0 && onSegment(l1.start, l2.end, l1.end)) {
        return true;
    }

    if (o3 == 0 && onSegment(l2.start, l1.start, l2.end)) {
        return true;
    }

    if (o4 == 0 && onSegment(l2.start, l1.end, l2.end)) {
        return true;
    }

    return false;
}

size_t countSelfIntersections(const std::vector<Point>& polygon) {
    size_t count = 0;
    size_t n = polygon.size();

    for (size_t i = 0; i < n; i++) {
        Line current = {polygon[i], polygon[(i + 1) % n]};
        for (size_t j = i + 1; j < n; j++) {
            Line other = {polygon[j], polygon[(j + 1) % n]};
            if (doIntersect(current, other)) {
                count++;
            }
        }
    }

    return count;
}

Matrix4 Matrix4::ViewMatrix(const Vector3& position, const Vector3& rotation) {
    Matrix4 viewMatrix;

    // Calculate the camera's forward, right, and up vectors based on the rotation
    Vector3 forward = Vector3(
        cos(rotation.y) * cos(rotation.x),
        sin(rotation.x),
        sin(rotation.y) * cos(rotation.x)
    ).normalize();

    Vector3 right = Vector3(
        sin(rotation.y - Maths::Radians(90.0f)),
        0,
        cos(rotation.y - Maths::Radians(90.0f))
    ).normalize();

    Vector3 up = right.cross(forward);

    // Set the view matrix based on the camera's position and orientation
    viewMatrix[0][0] = right.x;
    viewMatrix[1][0] = right.y;
    viewMatrix[2][0] = right.z;
    viewMatrix[3][0] = -right.dot(position);

    viewMatrix[0][1] = up.x;
    viewMatrix[1][1] = up.y;
    viewMatrix[2][1] = up.z;
    viewMatrix[3][1] = -up.dot(position);

    viewMatrix[0][2] = -forward.x;
    viewMatrix[1][2] = -forward.y;
    viewMatrix[2][2] = -forward.z;
    viewMatrix[3][2] = forward.dot(position);

    viewMatrix[0][3] = 0.0f;
    viewMatrix[1][3] = 0.0f;
    viewMatrix[2][3] = 0.0f;
    viewMatrix[3][3] = 1.0f;

    return viewMatrix;
}

