private:
    std::vector<unsigned long long> bits;

public:
    BitSet(int size) {
        bits.resize((size + 63) / 64, 0);
    }

    void set(int pos) {
        int index = pos / 64;
        int bit = pos % 64;
        bits[index] |= (1ULL << bit);
    }

    void clear(int pos) {
        int index = pos / 64;
        int bit = pos % 64;
        bits[index] &= ~(1ULL << bit);
    }

    bool get(int pos) {
        int index = pos / 64;
        int bit = pos % 64;
        return (bits[index] & (1ULL << bit)) != 0;
    }

    void andOp(BitSet& other) {
        for (size_t i = 0; i < bits.size(); ++i) {
            bits[i] &= other.bits[i];
        }
    }

    void orOp(BitSet& other) {
        for (size_t i = 0; i < bits.size(); ++i) {
            bits[i] |= other.bits[i];
        }
    }

    void xorOp(BitSet& other) {
        for (size_t i = 0; i < bits.size(); ++i) {
            bits[i] ^= other.bits[i];
        }
    }
};

