std::vector<glm::vec3> simulateParticles(const std::vector<glm::vec4>& start_position, 
                                         const std::vector<glm::vec4>& start_velocity, 
                                         float time_step, 
                                         float duration) {
    std::vector<glm::vec3> final_positions;

    for (size_t i = 0; i < start_position.size(); ++i) {
        glm::vec3 p = glm::vec3(start_position[i]);
        glm::vec3 v = glm::vec3(start_velocity[i]);

        float life = start_velocity[i].w;

        for (float t = 0; t < duration; t += time_step) {
            life -= time_step;
            if (life <= 0.f) {
                p = glm::vec3(start_position[i]);
                v = glm::vec3(start_velocity[i]);
