        Node* newNode = new Node(val);
        newNode->next = top;
        top = newNode;
    }

    void deleteTop() {
        if (top != nullptr) {
            Node* temp = top;
            top = top->next;
            delete temp;
        }
    }

    ~RedoDelete() {
        while (top != nullptr) {
            Node* temp = top;
            top = top->next;
            delete temp;
        }
    }
};

