#include <iostream>
#include <vector>
#include <string>

class Node {
public:
    std::string data;
    Node* next;
    Node(const std::string& value) : data(value), next(nullptr) {}
};

class LinkedList {
private:
    Node* head;
    int size;

public:
    LinkedList() : head(nullptr), size(0) {}

    void push_back(const std::string& value) {
        Node* new_node = new Node(value);
        if (head == nullptr) {
            head = new_node;
        } else {
            Node* current = head;
            while (current->next != nullptr) {
                current = current->next;
            }
            current->next = new_node;
        }
        size++;
    }

    void pop_back() {
        if (head == nullptr) {
            return;
        }
        if (head->next == nullptr) {
            delete head;
            head = nullptr;
        } else {
            Node* current = head;
            while (current->next->next != nullptr) {
                current = current->next;
            }
            delete current->next;
            current->next = nullptr;
        }
        size--;
    }

    int get_size() {
        return size;
    }

    std::string to_string() {
        std::string result;
        Node* current = head;
        while (current != nullptr) {
            result += current->data + " ";
            current = current->next;
