#include <string>

std::string clangFormat(const std::string& input) {
    std::string formattedCode;
    int indentationLevel = 0;
    bool withinQuotes = false;

    for (char c : input) {
        if (c == '{') {
            formattedCode += "\n" + std::string(indentationLevel, ' ');
            formattedCode += c;
            formattedCode += "\n" + std::string(++indentationLevel, ' ');
        } else if (c == '}') {
            formattedCode += "\n" + std::string(--indentationLevel, ' ');
            formattedCode += c;
            formattedCode += "\n" + std::string(indentationLevel, ' ');
        } else {
            formattedCode += c;
        }

        if (c == '"') {
            withinQuotes = !withinQuotes;
        }

        if (c == '\n' && !withinQuotes) {
            formattedCode += std::string(indentationLevel, ' ');
        }
    }

    return formattedCode;
}

