class PriorityQueue {
public:
    // Add a new element to the priority queue
    void AddElement(const Element& element) {
        auto it = elements_.find(element.GetId());
        if (it != elements_.end()) {
            if (it->second->GetPriority() < element.GetPriority()) {
                delete it->second;
                elements_.erase(it);
                addEntry = true;
            } else {
                addEntry = false;
            }
        } else {
            addEntry = true;
        }

        if (addEntry) {
            elements_[element.GetId()] = new Element(element);
        }
    }

