template<class T>
class Stack {
private:
    StackNode<T>* top;
    int maxSize;
    int minSize;
    int size;

public:
    Stack(int max, int min) {
        top = nullptr;
        maxSize = max;
        minSize = min;
        size = 0;
    }

    bool isEmpty() {
        return size == 0;
    }

    bool isFull() {
        return size == maxSize;
    }

    int getSize() {
        return size;
    }

    int getMaxSize() {
        return maxSize;
    }

    int getMinSize() {
        return minSize;
    }

    void push(T val) {
        if (isFull()) {
            cout << "Error: Stack is full." << endl;
            return;
        }

        StackNode<T>* newNode = new StackNode<T>(val);
        if (isEmpty()) {
            top = newNode;
        } else {
            top->next = newNode;
            newNode->prev = top;
            top = newNode;
        }

        size++;
    }

    T pop() {
        if (isEmpty()) {
            cout << "Error: Stack is empty." << endl;
            return T();
        }

        T val = top->data;
        StackNode<T>* temp = top;
        top = top->prev;
        delete temp;

        size--;
        return val;
    }

    T peek() {
        if (isEmpty()) {
            cout << "Error: Stack is empty." << endl;
            return T();
        }

        return top->data;
    }

    void display() {
        StackNode<T>* current = top;
        while (current != nullptr) {
            cout << current->data << " ";
            current = current->prev;
        }
        cout << endl;
    }

    T getMin() {
        if (isEmpty()) {
            cout << "Error: Stack is empty." << endl;
            return T();
        }

        return top->data;
    }

    T getMax() {
        if (isEmpty()) {
            cout << "Error: Stack is empty." << endl;
            return T();
        }

        StackNode<T>* current = top;
        T maxVal = current->data;
        while (current != nullptr) {
            if (current->data > maxVal) {
                maxVal = current->data;
            }
            current = current->prev;
        }

        return maxVal;
    }

    void reverse() {
        if (isEmpty()) {
            return;
        }

        StackNode<T>* current = top;
        StackNode<T>* temp;
        while (current != nullptr) {
            temp = current->prev;
            current->prev = current->next;
            current->next = temp;
            current = current->prev;
        }

        top = temp->prev;
    }
};

