    stack.push(10);
    stack.push(20);
    stack.push(30);
    cout << stack.getMin() << endl; // should output 10
    cout << stack.getMax() << endl; // should output 30
    stack.reverse();
    stack.display(); // should output 30 20 10

    return 0;
}

