        if (divisor == 0) {
            throw std::invalid_argument("Division by zero is not possible.");
        }

        return dividend % divisor;
    }
};

int main() {
    AdvancedCalculator calc;
    long long int result = calc.power(2, 10);
    std::cout << "Result of 2 raised to the power of 10: " << result << std::endl;

    int remainder = calc.modulus(15, 7);
    std::cout << "Remainder of 15 divided by 7: " << remainder << std::endl;

    try {
        int invalidModulus = calc.modulus(10, 0);
        std::cout << "This line should not be executed." << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Error: " << e.what() << std::endl;
    }

    return 0;
}

